#!/usr/bin/env python3
"""Create final evidence summary for the current working-tree release candidate."""
import csv,json,pathlib,statistics,time
ROOT=pathlib.Path(__file__).resolve().parents[5];OUT=pathlib.Path(__file__).resolve().parent;DOC=ROOT/'docs/8454H_V4_CURRENT_MAIN_VALIDATION.md'
def stats(x):return {'count':len(x),'mean':statistics.fmean(x),'median':statistics.median(x),'min':min(x),'max':max(x)}
steps=json.load(open(OUT/'progress.json'));libinfo=json.load(open(OUT/'candidate_library.json'));gate=json.load(open(OUT/'gate_all23.json'));noomp=json.load(open(OUT/'noomp_validation.json'));before=json.load(open(OUT/'source_fingerprint_before.json'));after=json.load(open(OUT/'source_fingerprint_after.json'))
if steps.get('status')!='complete' or gate.get('status')!='pass' or len(gate.get('cases',[]))!=23 or noomp.get('status')!='complete' or not after.get('unchanged'):raise SystemExit('incomplete validation record')
configs=[]
for mp in sorted((OUT/'matched').glob('*/matched_calls.json')):
 j=json.load(open(mp));m=j['run_config']
 assert m['control_sha256']=='73f0764610072b05a3e50afb8ce312fe6b717c361efef7b94e52f20bde63b42c'
 assert m['candidate_sha256']==libinfo['sha256'] and m['wait_policy_variant']=='runtime' and m['environment']['OMP_WAIT_POLICY'] is None and m['environment']['GOMP_SPINCOUNT'] is None
 for key,c in j['configurations'].items():
  assert c['complete'] and c['byte_exact_match'] and len(c['samples'])==m['reps']
  ss=c['samples']
  for s in ss:
   assert (s['calls']['control']['input_a_fnv1a64'],s['calls']['control']['input_b_fnv1a64'])==(s['calls']['candidate']['input_a_fnv1a64'],s['calls']['candidate']['input_b_fnv1a64'])
  mm={}
  for phase in ('api_wall_seconds','split_seconds','pack_seconds','compute_reconstruct_seconds','profile_total_seconds'):
   cv=[s['calls']['control'][phase] for s in ss];nv=[s['calls']['candidate'][phase] for s in ss];rr=[b/a for a,b in zip(cv,nv)]
   mm[phase]={'control_raw':cv,'candidate_raw':nv,'paired_candidate_over_control_raw':rr,'control_stats':stats(cv),'candidate_stats':stats(nv),'paired_ratio_stats':stats(rr),'ratio_of_arithmetic_mean_times':statistics.fmean(nv)/statistics.fmean(cv)}
  configs.append({'run_id':mp.parent.name,'precision':c['precision'],'budget':c['budget'],'N':c['N'],'reps':len(ss),'order':[s['order'] for s in ss],'metrics':mm,'fast_count_api':sum(r<1 for r in mm['api_wall_seconds']['paired_candidate_over_control_raw']),'byte_exact_match':c['byte_exact_match'],'output_sha256':c['output_sha256'],'input_fnv1a64':{'A':ss[0]['calls']['control']['input_a_fnv1a64'],'B':ss[0]['calls']['control']['input_b_fnv1a64']},'full_samples':ss})
if len(configs)!=8:raise SystemExit(f'expected 8 matched configs, got {len(configs)}')
with open(OUT/'onemkl_separate.csv',newline='') as f:mkl=list(csv.DictReader(f))
if len(mkl)!=10:raise SystemExit(f'expected 10 oneMKL rows, got {len(mkl)}')
for x in mkl:
 if 'Version 2026.1' not in x['mkl_version'] or x['mkl_threading_layer']!='GNU':raise SystemExit('unexpected oneMKL version/threading environment')
summary={'status':'pass','created_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'validation_directory':str(OUT),'working_tree_source_fingerprint_before':before,'working_tree_source_fingerprint_after':after,'main_openmp_library':libinfo,'frozen_v3_sha256':libinfo['frozen_v3_sha256'],'cmake_ctest_openmp':{'passed':True,'log':str(OUT/'logs/ctest.log'),'tests':3},'openmp_gate':gate,'no_openmp':noomp,'matched_runtime_policy':'runtime-default: OMP_WAIT_POLICY and GOMP_SPINCOUNT unset; 20ms parent park outside timed API; 64 CPUs 0-63','matched_configurations':configs,'oneMKL_separate_driver':{'path':str(OUT/'onemkl_separate.csv'),'command':json.load(open(OUT/'progress.json'))['steps'][-1]['command'],'environment':'MKL 2026.1, GNU threading, 64 threads, passive OpenMP wait; separate run, not interleaved','rows':mkl,'raw_csv_preserved':True}}
(OUT/'summary.json').write_text(json.dumps(summary,indent=2,sort_keys=True)+'\n')
lines=['# Current main candidate validation','',
 'This validates the current working-tree main candidate after adding the CompactWide FP32 dispatch guarded by `CACHE_BLOCK == 128`. It builds the actual CMake target and compares the resulting static archive with frozen V3 through a per-call interleaved persistent-process runner. This is a candidate-validation record, not a release declaration.','',
 f"Validation directory: `{OUT}`  ",f"Main archive SHA-256: `{libinfo['sha256']}`  ",f"Frozen V3 SHA-256: `{libinfo['frozen_v3_sha256']}`  ",f"`src/gemm.cpp` SHA-256: `{before['files']['src/gemm.cpp']}`  ",
 'The before/after fingerprints of CMakeLists, gemm/runtime sources, assembly, public header, and benchmark driver match. Full compile commands and logs are preserved. OpenMP configuration passed CTest 3/3; the original frozen 20 binary-gate cases plus three eligible CompactWide-specific cases passed. These verify full output and padding bytes on a padded eligible shape, eligible A=C alias semantics, and large-K overflow raising `ozamx::Error` while leaving the complete caller C allocation unchanged.','',
 '| Candidate | Gate case | Full C bytes compared | V3/Candidate output SHA-256 | Status |','|---|---|---:|---|---|']
for c in gate['cases'][-3:]:lines.append(f"| Main OpenMP | {c['case']} | {c['bytes_compared']} | `{c['full_output_sha256']['candidate']}` | pass |")
lines += ['',f"The no-OpenMP build also passed CTest 3/3. Its eligible FP32 4096³ full-output check matched frozen V3 SHA-256 `{noomp['full_output_sha256']['candidate']}` exactly (no-OpenMP archive SHA-256 `{noomp['candidate_library']['sha256']}`).","", '## Interleaved runtime-default matched calls','', 'Both children ran at 64 threads pinned to CPUs 0–63. `OMP_WAIT_POLICY` and `GOMP_SPINCOUNT` were unset, with a 20 ms parent pause after each child call outside the timed API. Each configuration checked deterministic input hashes and full C-output SHA-256. API wall is the primary end-to-end measure; candidate/control ratios below 1 favor the candidate. Mean paired ratios and medians remain separate from the ratio of arithmetic mean times; no samples were excluded.','', '| Workload | N | Reps | Fast calls | Median paired API ratio | Mean paired API ratio | Ratio of mean API times |','|---|---:|---:|---:|---:|---:|---:|']
for c in sorted(configs,key=lambda x:(x['precision'],x['budget'],x['N'])):
 label='FP32' if c['precision']=='fp32' else f"FP64 p{c['budget']}";t=c['metrics']['api_wall_seconds']
 lines.append(f"| {label} | {c['N']} | {c['reps']} | {c['fast_count_api']}/{c['reps']} | {t['paired_ratio_stats']['median']:.5f} | {t['paired_ratio_stats']['mean']:.5f} | {t['ratio_of_arithmetic_mean_times']:.5f} |")
lines += ['', 'Complete raw API and phase arrays, orders, input checksums, output hashes, warmup records, readiness/affinity data, and child binaries are retained in `summary.json` and individual journals. N=1024 contains four FP64 budget regressions and FP32; N=16384 FP32 is the fallback path because it lies outside CompactWide’s upper size bound. Its five samples are too few and unusually dispersed for a speed claim.','', 'At N=4096, the current main candidate is faster in 10/11 paired FP32 calls, with median 0.948 and arithmetic-mean API-time ratio 0.959. At N=8192 it is faster in 11/11, median 0.925 and ratio of mean API times 0.924. This supports a promising FP32 direction under this run, while retaining ordinary shared-host uncertainty; it does not prove a roofline ceiling or hardware guarantee.','', '## Separate oneMKL reference','', 'The existing standalone `bench/benchmark.cpp` driver was run separately (not interleaved with V3) for N=4096 and 8192, all five workloads, three timed repetitions, seed 260904 and uniform inputs. It reports a warmup, native profile/API wall timing, and oneMKL GEMM-only timing using Intel oneMKL 2026.1 with GNU threading and 64 threads. Its CSV contains all ten rows and raw native phase/API repetitions. Because MKL intervals cover GEMM only while ozAMX API wall includes preprocessing/allocation, compare timing scopes carefully; this is calibration context, not the matched V3 result.','', '| Workload | N | Main profile GFLOP/s | oneMKL GEMM GFLOP/s | Main profile / oneMKL ratio |','|---|---:|---:|---:|---:|']
for r in mkl:lines.append(f"| {r['precision']} p{r['budget']} | {r['N']} | {float(r['effective_GFLOP_s']):.1f} | {float(r['mkl_effective_GFLOP_s']):.1f} | {float(r['profile_speedup']):.3f} |")
lines += ['', 'The standalone CSV records the exact oneMKL version, library path, GNU threading layer, seed, phase profile, API wall, and native/MKL timings. No paper precision claim is inferred from these comparisons.','']
DOC.write_text('\n'.join(lines));print(json.dumps({'summary':str(OUT/'summary.json'),'documentation':str(DOC),'matched_configs':len(configs),'gate_cases':len(gate['cases']),'onemkl_rows':len(mkl)},indent=2))
